        raise ValueError("Cannot compute median of empty list")
    ordered = sorted(values)
    n = len(ordered)
    if n % 2 == 1:
        return ordered[n // 2]
    else:
        mid1 = ordered[n // 2 - 1]
        mid2 = ordered[n // 2]
        return (mid1 + mid2) / 2

